SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百〇一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f4628c87dbbe735d6f3c2/content/books/zizhi-tongjian/vol-288/year-0948/part-06/sources/library/jiuwudaishi-101-august-948/source.txt", "note": "《旧五代史》卷一百〇一，段落 jiu-wudaishi-205deb4a7860-p002458；EPUB电子本，纸本及异文待核", "id": "e3020a52-b8f3-532c-aa8d-f2572696bc9b"}, {"title": "宋史·巻二百五十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f4628c87dbbe735d6f3c2/content/books/zizhi-tongjian/vol-288/year-0948/part-06/sources/library/songshi-254-hu-hezhong-strategy/source.txt", "note": "《宋史》巻二百五十四，段落 songshi-9c6e46fee832-p057472；EPUB电子本，纸本及异文待核", "id": "25b4cb98-11c5-565c-a590-860e65f0aa9e"}, {"title": "资治通鉴·后汉纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f4628c87dbbe735d6f3c2/content/books/zizhi-tongjian/vol-288/year-0948/part-06/sources/library/tongjian-288-948-august-september/source.txt", "note": "《资治通鉴》后汉纪三，段落 zizhi-tongjian-a63549944a71-p003418；电子底本待考，分段待核", "id": "59171fec-2ee4-563c-bfb5-8250bc322756"}, {"title": "新五代史·卷十一", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f4628c87dbbe735d6f3c2/content/books/zizhi-tongjian/vol-288/year-0948/part-06/sources/library/xinwudaishi-011-guo-dispatch/source.txt", "note": "《新五代史》卷十一，段落 xin-wudaishi-b08f244b9241-p000361；EPUB电子本，纸本及异文待核", "id": "ae374b55-4ad2-521c-91c4-9fe936bcbfc1"}, {"title": "新五代史·卷十一", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e4f57a30a26d134a760f