INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李昊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光三年条所见人物：李昊。", "biography": null, "status": "draft", "id": "ecf7855b-2568-576c-b0b9-58e6b1f120fa"}, {"name": "徐光溥", "aliases": ["徐光溥（后蜀官员）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀官员。948年由翰林学士、兵部侍郎任中书侍郎兼礼部尚书，与李昊一同加同平章事。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "6d13e792-75d4-5b0e-a25d-12e4b92f9796"}, {"name": "安思谦", "aliases": ["安思謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安思谦，茶酒库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "6ec752d6-91f9-5760-8ea8-c552e6369345"}, {"name": "赵廷隐", "aliases": ["趙廷隱"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：赵廷隐。", "biography": null, "status": "draft", "id": "bc139832-e17d-51c1-b2c5-a6b9fcca1a14"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}, {"name": "赵晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：赵晖。", "biography": null, "status": "draft", "id": "9efd6fe6-4ba6-5e2b-99cc-751822d75039"}, {"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "郑珙", "aliases": ["鄭珙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "青州人，刘崇的节度判官。刘崇因与郭威有嫌隙而忧惧时，郑珙劝他谋求自保；《新五代史》也记类似谋议，但安排在郭威讨平三镇之后，与《资治通鉴》的叙述顺序不同。生卒年未据本次原文确定。", "biography": null, "status": "draft", "id": "d8579c34-3e02-5140-b6af-9f52a59f202e"}, {"name": "常思", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉昭义节度使。948年讨伐李守贞等三镇时曾驻潼关，后来与郭威、白文珂、刘词分三路进攻河中。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "1d3a1e89-5826-52d4-ba66-55dbc3d91e22"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "赵思绾", "aliases": ["趙思綰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州人，原在赵在礼军中，后来成为赵匡赞牙将。948年王景崇试图令赵匡赞牙兵刺面防逃时，主动提出先刺自己以率众。齐藏珍建议将其杀死，王景崇不听。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b571162d-9596-5439-a443-f33cd87ea628"}, {"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "扈彦珂", "aliases": ["扈彥珂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉镇国节度使。948年郭威督军讨伐三镇时，建议先攻作为盟主的李守贞，避免先攻长安、凤翔而腹背受敌，郭威采纳。生卒年未据本次原文确定。", "biography": null, "status": "draft", "id": "b3dfa0c2-3df0-5a4f-8c4b-33791166e22a"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

